namespace opencensus {
namespace context {

// Context holds information specific to an operation, such as a TagMap and
// Span. Each thread has a currently active Context. Contexts are conceptually
// immutable: the contents of a Context cannot be modified in-place.
//
// This is a draft implementation of Context, and we chose to depend on TagMap
// and Span directly. In future, the implementation will change, so only rely
// on the public API for manipulating Contexts. In future we may support
// arbitrary keys and values.
class Context {
 public:
  // Returns a const reference to the current (thread local) Context.
  static const Context& Current();

  // Context is copiable and movable.
  Context(const Context&) = default;
  Context(Context&&) = default;
  Context& operator=(const Context&) = default;
  Context& operator=(Context&&) = default;

  // Returns an std::function wrapped to run with a copy of this Context.
  std::function<void()> Wrap(std::function<void()> fn) const;

  // Returns a human-readable string for debugging. Do not rely on its format or
  // try to parse it. Do not use the DebugString to retrieve Spans or Tags.
  std::string DebugString() const;

 private:
  // Creates a default Context.
  Context();

  static Context* InternalMutableCurrent();
  friend void swap(Context& a, Context& b);

  friend class ContextTestPeer;
  friend class WithContext;
  friend class ContextWrapper;
  friend class ::opencensus::tags::ContextPeer;
  friend class ::opencensus::tags::WithTagMap;
  friend class ::opencensus::trace::ContextPeer;
  friend class ::opencensus::trace::WithSpan;

  opencensus::tags::TagMap tags_;
  opencensus::trace::Span span_;
};

}  // namespace context
}  // namespace opencensus

namespace opencensus {
namespace context {

// WithContext is a scoped object that sets the current Context to the given
// one, until the WithContext object is destroyed. If the condition is false, it
// doesn't do anything.
//
// Because WithContext changes the current (thread local) context, NEVER
// allocate a WithContext in one thread and deallocate in another. A simple way
// to ensure this is to only ever stack-allocate it.
//
// Example usage:
// {
//   WithContext wc(op.ctx_);
//   // Do work.
// }
class WithContext {
 public:
  explicit WithContext(const Context& ctx, bool cond = true);
  explicit WithContext(Context&& ctx, bool cond = true);
  ~WithContext();

 private:
  WithContext() = delete;
  WithContext(const WithContext&) = delete;
  WithContext(WithContext&&) = delete;
  WithContext& operator=(const WithContext&) = delete;
  WithContext& operator=(WithContext&&) = delete;

  void ConditionalSwap();

  Context swapped_context_;
#ifndef NDEBUG
  const Context* original_context_;
#endif
  const bool cond_;
};

}  // namespace context
}  // namespace opencensus

namespace opencensus {
namespace tags {

// TagKey is a lightweight, immutable representation of a tag key. It has a
// trivial destructor and can be safely used as a local static variable.
// TagKey is thread-safe.
class TagKey final {
 public:
  // Registers a tag key with 'name'. Registering the same name twice produces
  // equal TagKeys.
  static TagKey Register(absl::string_view name);

  const std::string& name() const;

  bool operator==(TagKey other) const { return id_ == other.id_; }
  bool operator!=(TagKey other) const { return id_ != other.id_; }
  bool operator<(TagKey other) const { return id_ < other.id_; }

  // Returns a suitable hash of the TagKey. The implementation may change.
  ABSL_DEPRECATED(
      "Use absl::Hash<TagKey>()(...) instead. "
      "This method will be removed on or after 2020-02-06")
  std::size_t hash() const { return id_; }

  template <typename H>
  friend H AbslHashValue(H state, const TagKey& k) {
    return H::combine(std::move(state), k.id_);
  }

 private:
  friend class TagKeyRegistry;
  explicit TagKey(uint64_t id) : id_(id) {}

  uint64_t id_;
};

}  // namespace tags
}  // namespace opencensus

namespace opencensus {
namespace tags {

// TagMap represents an immutable map of TagKeys to tag values (strings), and
// provides efficient equality and hash operations. A TagMap is expensive to
// construct, and should be shared between uses where possible.
class TagMap final {
 public:
  // Both constructors are not explicit so that Record({}, {{"k", "v"}}) works.
  // This constructor is needed because even though we copy to a vector
  // internally because c++ cannot deduce the conversion needed.
  TagMap(std::initializer_list<std::pair<TagKey, absl::string_view>> tags);

  // This constructor is needed so that callers can dynamically construct
  // TagMaps. It takes the argument by value to allow it to be moved.
  TagMap(std::vector<std::pair<TagKey, std::string>> tags);

  // Accesses the tags sorted by key (in an implementation-defined, not
  // lexicographic, order).
  const std::vector<std::pair<TagKey, std::string>>& tags() const {
    return tags_;
  }

  struct Hash {
    std::size_t operator()(const TagMap& tags) const;
  };

  bool operator==(const TagMap& other) const;
  bool operator!=(const TagMap& other) const { return !(*this == other); }

  // Returns a human-readable string for debugging. Do not rely on its format or
  // try to parse it. Do not use it to retrieve tags.
  std::string DebugString() const;

 private:
  void Initialize();

  std::size_t hash_;
  // TODO: add an option to store string_views to avoid copies.
  std::vector<std::pair<TagKey, std::string>> tags_;
};

}  // namespace tags
}  // namespace opencensus

struct Hash {
    std::size_t operator()(const TagMap& tags) const;
  };

namespace opencensus {
namespace tags {

// WithTagMap is a scoped object that sets the current TagMap to the given one,
// until the WithTagMap object is destroyed. If the condition is false, it
// doesn't do anything.
//
// Because WithTagMap changes the current (thread local) context, NEVER allocate
// a WithTagMap in one thread and deallocate in another. A simple way to ensure
// this is to only ever stack-allocate it.
//
// Example usage:
// {
//   WithTagMap wt(tags);
//   // Do work.
// }
class WithTagMap {
 public:
  explicit WithTagMap(const TagMap& tags, bool cond = true);
  explicit WithTagMap(TagMap&& tags, bool cond = true);
  ~WithTagMap();

 private:
  WithTagMap() = delete;
  WithTagMap(const WithTagMap&) = delete;
  WithTagMap(WithTagMap&&) = delete;
  WithTagMap& operator=(const WithTagMap&) = delete;
  WithTagMap& operator=(WithTagMap&&) = delete;

  void ConditionalSwap();

  TagMap swapped_tags_;
#ifndef NDEBUG
  const ::opencensus::context::Context* original_context_;
#endif
  const bool cond_;
};

}  // namespace tags
}  // namespace opencensus

namespace opencensus {
namespace trace {

// The canonical error codes for Google APIs.
// https://github.com/googleapis/googleapis/blob/master/google/rpc/code.proto
enum StatusCode : uint8_t {
  // Not an error; returned on success
  //
  // HTTP Mapping: 200 OK
  OK = 0,

  // The operation was cancelled, typically by the caller.
  //
  // HTTP Mapping: 499 Client Closed Request
  CANCELLED = 1,

  // Unknown error.  For example, this error may be returned when
  // a `Status` value received from another address space belongs to
  // an error space that is not known in this address space.  Also
  // errors raised by APIs that do not return enough error information
  // may be converted to this error.
  //
  // HTTP Mapping: 500 Internal Server Error
  UNKNOWN = 2,

  // The client specified an invalid argument.  Note that this differs
  // from `FAILED_PRECONDITION`.  `INVALID_ARGUMENT` indicates arguments
  // that are problematic regardless of the state of the system
  // (e.g., a malformed file name).
  //
  // HTTP Mapping: 400 Bad Request
  INVALID_ARGUMENT = 3,

  // The deadline expired before the operation could complete. For operations
  // that change the state of the system, this error may be returned
  // even if the operation has completed successfully.  For example, a
  // successful response from a server could have been delayed long
  // enough for the deadline to expire.
  //
  // HTTP Mapping: 504 Gateway Timeout
  DEADLINE_EXCEEDED = 4,

  // Some requested entity (e.g., file or directory) was not found.
  //
  // Note to server developers: if a request is denied for an entire class
  // of users, such as gradual feature rollout or undocumented whitelist,
  // `NOT_FOUND` may be used. If a request is denied for some users within
  // a class of users, such as user-based access control, `PERMISSION_DENIED`
  // must be used.
  //
  // HTTP Mapping: 404 Not Found
  NOT_FOUND = 5,

  // The entity that a client attempted to create (e.g., file or directory)
  // already exists.
  //
  // HTTP Mapping: 409 Conflict
  ALREADY_EXISTS = 6,

  // The caller does not have permission to execute the specified
  // operation. `PERMISSION_DENIED` must not be used for rejections
  // caused by exhausting some resource (use `RESOURCE_EXHAUSTED`
  // instead for those errors). `PERMISSION_DENIED` must not be
  // used if the caller can not be identified (use `UNAUTHENTICATED`
  // instead for those errors). This error code does not imply the
  // request is valid or the requested entity exists or satisfies
  // other pre-conditions.
  //
  // HTTP Mapping: 403 Forbidden
  PERMISSION_DENIED = 7,

  // The request does not have valid authentication credentials for the
  // operation.
  //
  // HTTP Mapping: 401 Unauthorized
  UNAUTHENTICATED = 16,

  // Some resource has been exhausted, perhaps a per-user quota, or
  // perhaps the entire file system is out of space.
  //
  // HTTP Mapping: 429 Too Many Requests
  RESOURCE_EXHAUSTED = 8,

  // The operation was rejected because the system is not in a state
  // required for the operation's execution.  For example, the directory
  // to be deleted is non-empty, an rmdir operation is applied to
  // a non-directory, etc.
  //
  // Service implementors can use the following guidelines to decide
  // between `FAILED_PRECONDITION`, `ABORTED`, and `UNAVAILABLE`:
  //  (a) Use `UNAVAILABLE` if the client can retry just the failing call.
  //  (b) Use `ABORTED` if the client should retry at a higher level
  //      (e.g., when a client-specified test-and-set fails, indicating the
  //      client should restart a read-modify-write sequence).
  //  (c) Use `FAILED_PRECONDITION` if the client should not retry until
  //      the system state has been explicitly fixed.  E.g., if an "rmdir"
  //      fails because the directory is non-empty, `FAILED_PRECONDITION`
  //      should be returned since the client should not retry unless
  //      the files are deleted from the directory.
  //
  // HTTP Mapping: 400 Bad Request
  FAILED_PRECONDITION = 9,

  // The operation was aborted, typically due to a concurrency issue such as
  // a sequencer check failure or transaction abort.
  //
  // See the guidelines above for deciding between `FAILED_PRECONDITION`,
  // `ABORTED`, and `UNAVAILABLE`.
  //
  // HTTP Mapping: 409 Conflict
  ABORTED = 10,

  // The operation was attempted past the valid range.  E.g., seeking or
  // reading past end-of-file.
  //
  // Unlike `INVALID_ARGUMENT`, this error indicates a problem that may
  // be fixed if the system state changes. For example, a 32-bit file
  // system will generate `INVALID_ARGUMENT` if asked to read at an
  // offset that is not in the range [0,2^32-1], but it will generate
  // `OUT_OF_RANGE` if asked to read from an offset past the current
  // file size.
  //
  // There is a fair bit of overlap between `FAILED_PRECONDITION` and
  // `OUT_OF_RANGE`.  We recommend using `OUT_OF_RANGE` (the more specific
  // error) when it applies so that callers who are iterating through
  // a space can easily look for an `OUT_OF_RANGE` error to detect when
  // they are done.
  //
  // HTTP Mapping: 400 Bad Request
  OUT_OF_RANGE = 11,

  // The operation is not implemented or is not supported/enabled in this
  // service.
  //
  // HTTP Mapping: 501 Not Implemented
  UNIMPLEMENTED = 12,

  // Internal errors.  This means that some invariants expected by the
  // underlying system have been broken.  This error code is reserved
  // for serious errors.
  //
  // HTTP Mapping: 500 Internal Server Error
  INTERNAL = 13,

  // The service is currently unavailable.  This is most likely a
  // transient condition, which can be corrected by retrying with
  // a backoff.
  //
  // See the guidelines above for deciding between `FAILED_PRECONDITION`,
  // `ABORTED`, and `UNAVAILABLE`.
  //
  // HTTP Mapping: 503 Service Unavailable
  UNAVAILABLE = 14,

  // Unrecoverable data loss or corruption.
  //
  // HTTP Mapping: 500 Internal Server Error
  DATA_LOSS = 15,
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

class AttributeValueRef final {
 public:
  enum class Type : uint8_t { kString, kBool, kInt };

  AttributeValueRef(const AttributeValueRef&) = default;
  AttributeValueRef(AttributeValueRef&&) = default;
  AttributeValueRef& operator=(const AttributeValueRef&) = default;
  AttributeValueRef& operator=(AttributeValueRef&&) = default;

  AttributeValueRef(absl::string_view string_value)
      : string_value_(string_value), type_(Type::kString) {}

  AttributeValueRef(const char* string_value)
      : string_value_(string_value), type_(Type::kString) {}

  template <typename Allocator>
  AttributeValueRef(const std::basic_string<char, std::char_traits<char>,
                                            Allocator>& string_value)
      : string_value_(string_value), type_(Type::kString) {}

  template <typename T, typename std::enable_if<
                            std::is_integral<T>::value &&
                            !std::is_same<T, bool>::value>::type* = nullptr>
  AttributeValueRef(T int_value) : int_value_(int_value), type_(Type::kInt) {}

  template <typename T, typename std::enable_if<
                            std::is_same<T, bool>::value>::type* = nullptr>
  AttributeValueRef(T bool_value)
      : bool_value_(bool_value), type_(Type::kBool) {}

  Type type() const { return type_; }
  absl::string_view string_value() const;
  bool bool_value() const;
  int64_t int_value() const;

  bool operator==(const AttributeValueRef& v) const;
  bool operator!=(const AttributeValueRef& v) const;

  std::string DebugString() const;

 private:
  union {
    absl::string_view string_value_;
    int64_t int_value_;
    bool bool_value_;
  };
  Type type_;
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

class Span;

// Samplers decide whether or not a given Span will be sampled.
// All implementations of Sampler must be thread-safe!
class Sampler {
 public:
  virtual ~Sampler() = default;

  // Returns true if a Span with the following data should be sampled. If there
  // is no parent, then parent_context will be nullptr. The lifetime of the
  // parent_context has to be valid for the duration of the ShouldSample() call.
  // The Sampler must not hold on to the pointer.
  virtual bool ShouldSample(const SpanContext* parent_context,
                            bool has_remote_parent, const TraceId& trace_id,
                            const SpanId& span_id, absl::string_view name,
                            const std::vector<Span*>& parent_links) const = 0;
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

class ProbabilitySampler final : public Sampler {
 public:
  explicit ProbabilitySampler(double probability);

  bool ShouldSample(const SpanContext* parent_context, bool has_remote_parent,
                    const TraceId& trace_id, const SpanId& span_id,
                    absl::string_view name,
                    const std::vector<Span*>& parent_links) const override;

 private:
  friend class TraceParamsImpl;  // For the global ProbabilitySampler.
  explicit ProbabilitySampler(uint64_t threshold) : threshold_(threshold) {}

  // Probability is converted to a value between [0, UINT64_MAX].
  const uint64_t threshold_;
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

class AlwaysSampler final : public Sampler {
 public:
  bool ShouldSample(const SpanContext* parent_context ABSL_ATTRIBUTE_UNUSED,
                    bool has_remote_parent ABSL_ATTRIBUTE_UNUSED,
                    const TraceId& trace_id ABSL_ATTRIBUTE_UNUSED,
                    const SpanId& span_id ABSL_ATTRIBUTE_UNUSED,
                    absl::string_view name ABSL_ATTRIBUTE_UNUSED,
                    const std::vector<Span*>& parent_links
                        ABSL_ATTRIBUTE_UNUSED) const override {
    return true;
  }
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

class NeverSampler final : public Sampler {
 public:
  bool ShouldSample(const SpanContext* parent_context ABSL_ATTRIBUTE_UNUSED,
                    bool has_remote_parent ABSL_ATTRIBUTE_UNUSED,
                    const TraceId& trace_id ABSL_ATTRIBUTE_UNUSED,
                    const SpanId& span_id ABSL_ATTRIBUTE_UNUSED,
                    absl::string_view name ABSL_ATTRIBUTE_UNUSED,
                    const std::vector<Span*>& parent_links
                        ABSL_ATTRIBUTE_UNUSED) const override {
    return false;
  }
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

// SpanId represents an opaque 64-bit span identifier that uniquely identifies a
// span within a trace. SpanId is immutable.
class SpanId final {
 public:
  // The size in bytes of the SpanId.
  static constexpr size_t kSize = 8;

  // An invalid SpanId (all zeros).
  SpanId() : rep_{0} {}

  // Creates a SpanId by copying the first kSize bytes from the buffer.
  explicit SpanId(const uint8_t* buf);

  // Returns a 16-char hex string of the SpanId value.
  std::string ToHex() const;

  // Returns a pointer to the opaque value.
  const void* Value() const;

  bool operator==(const SpanId& that) const;

  // Returns false if the SpanId is all zeros.
  bool IsValid() const;

  // Copies the opaque SpanId data to a buffer, which must hold kSize bytes.
  void CopyTo(uint8_t* buf) const;

 private:
  uint8_t rep_[kSize];
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

// TraceId represents an opaque 128-bit trace identifier. The trace identifier
// remains constant across the trace. TraceId is immutable.
class TraceId final {
 public:
  // The size in bytes of the TraceId.
  static constexpr size_t kSize = 16;

  // An invalid TraceId (all zeros).
  TraceId() : rep_{0} {}

  // Creates a TraceId by copying the first kSize bytes from the buffer.
  explicit TraceId(const uint8_t* buf);

  // Returns a 32-char hex string of the TraceId value.
  std::string ToHex() const;

  // Returns a pointer to the opaque value.
  const void* Value() const;

  bool operator==(const TraceId& that) const;

  // Returns false if the TraceId is all zeros.
  bool IsValid() const;

  // Copies the opaque TraceId data to a buffer, which must hold kSize bytes.
  void CopyTo(uint8_t* buf) const;

 private:
  uint8_t rep_[kSize];
};

}  // namespace trace
}  // namespace opencensus

class TraceOptions final {
 public:
  // The size in bytes of the TraceOptions.
  static constexpr size_t kSize = 1;

  // No options are enabled by default.
  TraceOptions() : rep_{0} {}

  // Creates TraceOptions from a buffer of exactly kSize bytes.
  explicit TraceOptions(const uint8_t* buf);

  // IsSampled means that the trace should be sampled for exporting outside of
  // the process, e.g. to Stackdriver/Zipkin.
  bool IsSampled() const;

  bool operator==(const TraceOptions& that) const;

  // Returns a 2-char hex string of the TraceOptions value.
  std::string ToHex() const;

  // Copies the TraceOptions data to a buffer, which must hold kSize bytes.
  void CopyTo(uint8_t* buf) const;

  // Returns a copy of these TraceOptions with the sampled bit set to
  // is_sampled.
  TraceOptions WithSampling(bool is_sampled) const;

 private:
  uint8_t rep_[kSize];
};

namespace opencensus {
namespace trace {

// SpanContext contains the state that must propagate to child spans and across
// process boundaries. It contains the TraceId and SpanId associated with the
// span and a set of TraceOptions. SpanContext is immutable.
class SpanContext final {
 public:
  // Blank SpanContext: TraceId, SpanId, and TraceOptions are 0.
  SpanContext() {}

  // SpanContext is copyable and movable.
  SpanContext(const SpanContext&) = default;
  SpanContext(SpanContext&&) = default;
  SpanContext& operator=(const SpanContext&) = default;
  SpanContext& operator=(SpanContext&&) = default;

  SpanContext(TraceId trace_id, SpanId span_id,
              TraceOptions trace_options = TraceOptions())
      : trace_id_(trace_id), span_id_(span_id), trace_options_(trace_options) {}

  // Returns the TraceId associated with this SpanContext.
  TraceId trace_id() const { return trace_id_; }

  // Returns the SpanId associated with this SpanContext.
  SpanId span_id() const { return span_id_; }

  // Returns the TraceOptions associated with this SpanContext.
  TraceOptions trace_options() const { return trace_options_; }

  // Compares two SpanContexts for equality. Only compares TraceId and SpanId,
  // not TraceOptions!
  bool operator==(const SpanContext& that) const;

  // Compares two SpanContexts for inequality. Only compares TraceId and SpanId,
  // not TraceOptions!
  bool operator!=(const SpanContext& that) const;

  // Returns true if SpanId and TraceId are valid.
  bool IsValid() const;

  // Returns hex strings separated with hyphens, e.g. "trace_id-span_id-options"
  std::string ToString() const;

 private:
  TraceId trace_id_;
  SpanId span_id_;
  TraceOptions trace_options_;
};

}  // namespace trace
}  // namespace opencensus

struct TraceParams final {
  uint32_t max_attributes;
  uint32_t max_annotations;
  uint32_t max_message_events;
  uint32_t max_links;
  ProbabilitySampler sampler;
};

namespace opencensus {
namespace trace {

// TraceConfig holds the currently active TraceParams.
// TraceConfig is thread-safe.
class TraceConfig {
 public:
  // Sets the currently active TraceParams. Doing this is not atomic: individual
  // parts of the active TraceParams are updated separately.
  static void SetCurrentTraceParams(const TraceParams& params);
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace trace {

// WithSpan is a scoped object that sets the current Span to the given one,
// until the WithSpan object is destroyed. If the condition is false, it doesn't
// do anything. If the condition is true and end_span is true, it calls End() on
// the Span when it falls out of scope.
//
// Because WithSpan changes the current (thread local) context, NEVER allocate a
// WithSpan in one thread and deallocate in another. A simple way to ensure this
// is to only ever stack-allocate it.
//
// Example usage:
// {
//   WithSpan ws(span);
//   // Do work.
// }
class WithSpan {
 public:
  explicit WithSpan(const Span& span, bool cond = true, bool end_span = false);
  ~WithSpan();

  // No Span&& constructor because it encourages "consuming" the Span with a
  // std::move(). It's better to hold on to the Span object because we have to
  // call End() on it when the operation is finished.

 private:
  WithSpan() = delete;
  WithSpan(const WithSpan&) = delete;
  WithSpan(WithSpan&&) = delete;
  WithSpan& operator=(const WithSpan&) = delete;
  WithSpan& operator=(WithSpan&&) = delete;

  void ConditionalSwap();

  Span swapped_span_;
#ifndef NDEBUG
  const ::opencensus::context::Context* original_context_;
#endif
  const bool cond_;
  const bool end_span_;
};

}  // namespace trace
}  // namespace opencensus

namespace opencensus {
namespace stats {

// BucketBoundaries defines the bucket boundaries for distribution
// aggregations.
// BucketBoundaries is a value type, and is thread-compatible.
class BucketBoundaries final {
 public:
  // Creates a BucketBoundaries with num_finite_buckets each 'width' wide,
  // as well as an underflow and overflow bucket. 'offset' is the lower bound of
  // the first finite bucket, so finite bucket i (1 <= i <= num_finite_buckets)
  // covers the interval [offset + (i - 1) * width, offset + i * width). The
  // underflow bucket covers [-inf, offset) and the overflow bucket [offset +
  // num_finite_buckets * width, inf].
  static BucketBoundaries Linear(int num_finite_buckets, double offset,
                                 double width);

  // Creates a BucketBoundaries with num_finite_buckets with exponentially
  // increasing boundaries starting at zero (governed by growth_factor and
  // scale), as well as an underflow and overflow bucket. Finite bucket i (1 <=
  // i <= num_finite_buckets) covers the interval [scale * growth_factor ^ (i -
  // 1), scale * growth_factor ^ i). The underflow bucket covers [-inf, 0) and
  // the overflow bucket [scale * growth_factor ^ num_finite_buckets, inf].
  static BucketBoundaries Exponential(int num_finite_buckets, double scale,
                                      double growth_factor);

  // Creates a BucketBoundaries from a monotonically increasing list of
  // boundaries. This will create a bucket covering each interval of
  // [boundaries[i], boundaries[i+1]), as well as an underflow bucket covering
  // [-inf, boundaries[0]) and an overflow bucket covering
  // [boundaries[boundaries.size()-1], inf].
  static BucketBoundaries Explicit(std::vector<double> boundaries);

  // The number of buckets in a Distribution using this bucketer.
  int num_buckets() const { return lower_boundaries_.size() + 1; }
  // The index of the bucket for a given value, in [0, num_buckets() - 1].
  int BucketForValue(double value) const;

  const std::vector<double>& lower_boundaries() const {
    return lower_boundaries_;
  }

  std::string DebugString() const;

  bool operator==(const BucketBoundaries& other) const {
    return lower_boundaries_ == other.lower_boundaries_;
  }
  bool operator!=(const BucketBoundaries& other) const {
    return !(*this == other);
  }

 private:
  BucketBoundaries(std::vector<double> lower_boundaries)
      : lower_boundaries_(std::move(lower_boundaries)) {}

  // The lower bound of each bucket, excluding the underflow bucket but
  // including the overflow bucket.
  std::vector<double> lower_boundaries_;
};

}  // namespace stats
}  // namespace opencensus

namespace opencensus {
namespace stats {

// Aggregation defines how to aggregate data for each view. See the static
// constructors for details of the various options.
// Aggregation is immutable.
class Aggregation final {
 public:
  // Count aggregation counts the number of records, ignoring their individual
  // values. Note that 'count' measures (e.g. the count of RPCs received) should
  // use Sum() aggregation to correctly handle non-unit recorded values.
  static Aggregation Count() {
    return Aggregation(Type::kCount, BucketBoundaries::Explicit({}));
  }

  // Sum aggregation sums all records.
  static Aggregation Sum() {
    return Aggregation(Type::kSum, BucketBoundaries::Explicit({}));
  }

  // Distribution aggregation calculates distribution statistics (count, mean,
  // range, and sum of squared deviation) and tracks a histogram of recorded
  // values according to 'buckets'.
  static Aggregation Distribution(BucketBoundaries buckets) {
    return Aggregation(Type::kDistribution, std::move(buckets));
  }

  // LastValue aggregation returns the last value recorded.
  static Aggregation LastValue() {
    return Aggregation(Type::kLastValue, BucketBoundaries::Explicit({}));
  }

  enum class Type {
    kCount,
    kSum,
    kDistribution,
    kLastValue,
  };

  Type type() const { return type_; }
  const BucketBoundaries& bucket_boundaries() const {
    return bucket_boundaries_;
  }

  std::string DebugString() const;

  bool operator==(const Aggregation& other) const {
    return type_ == other.type_ &&
           bucket_boundaries_ == other.bucket_boundaries_;
  }
  bool operator!=(const Aggregation& other) const { return !(*this == other); }

 private:
  Aggregation(Type type, BucketBoundaries buckets)
      : type_(type), bucket_boundaries_(std::move(buckets)) {}

  Type type_;
  // Ignored except if type_ == kDistribution.
  BucketBoundaries bucket_boundaries_;
};

}  // namespace stats
}  // namespace opencensus

