import os
import random
import struct
from typing import List

# Target data type: fixed-length 16-byte binary (e.g., TraceId)
# We generate interesting but valid 16-byte sequences that exercise
# different code paths in samplers and span/context construction.
# The fuzzer stubs will also derive 8-byte SpanId and 1-byte TraceOptions
# from FUZZ_PARAM(uint8_t[N]) and FUZZ_PARAM_STR() paths, but our single
# seed buffer is fed into FUZZ_PARAM_STR/FUZZ_PARAM and split by the
# fuzzing framework. We therefore pack multiple useful 16-byte chunks
# plus some ASCII names into one buffer to seed those calls.

MAX_TOTAL = 4096


def _randbytes(rng: random.Random, n: int) -> bytes:
    # Use deterministic RNG to produce bytes
    return bytes(rng.getrandbits(8) for _ in range(n))


def _mk_trace_id_pattern(kind: str, rng: random.Random) -> bytes:
    # Produce 16-byte patterns with different characteristics
    if kind == "all_zero":
        return b"\x00" * 16
    if kind == "all_ff":
        return b"\xff" * 16
    if kind == "low_nonzero":
        # only last byte non-zero
        return b"\x00" * 15 + bytes([rng.randrange(1, 256)])
    if kind == "high_nonzero":
        # first byte non-zero, rest zero
        return bytes([rng.randrange(1, 256)]) + b"\x00" * 15
    if kind == "alternating":
        return bytes((0xAA if i % 2 == 0 else 0x55) for i in range(16))
    if kind == "increasing":
        start = rng.randrange(0, 240)
        return bytes((start + i) & 0xFF for i in range(16))
    if kind == "random":
        return _randbytes(rng, 16)
    # default
    return _randbytes(rng, 16)


def _mk_span_id_pattern(kind: str, rng: random.Random) -> bytes:
    # 8-byte span id patterns; similar diversity
    if kind == "all_zero":
        return b"\x00" * 8
    if kind == "all_ff":
        return b"\xff" * 8
    if kind == "single_bit":
        bit = 1 << rng.randrange(0, 8)
        return bytes([bit]) + b"\x00" * 7
    if kind == "alternating":
        return bytes((0xAA if i % 2 == 0 else 0x55) for i in range(8))
    if kind == "random":
        return _randbytes(rng, 8)
    return _randbytes(rng, 8)


def _mk_trace_options(rng: random.Random) -> bytes:
    # 1-byte flags; vary sampled bit and random others
    sampled = rng.choice([0x00, 0x01])
    other = rng.randrange(0, 256) & 0xFE  # ensure LSB can be controlled by sampled
    val = (other | (sampled & 0x01)) & 0xFF
    return bytes([val])


def _ascii_name(rng: random.Random) -> bytes:
    # Construct span names with varying lengths and characters
    choices = [
        b"root",
        b"child",
        b"db.query",
        b"HTTP GET /health",
        b"unicode:\xe2\x98\x83",  # snowman in UTF-8
        b"",
    ]
    base = rng.choice(choices)
    # Optionally add a numeric suffix
    if rng.random() < 0.6:
        base += ("#" + str(rng.randrange(0, 100000))).encode("ascii")
    return base


def _chunk(tag: bytes, payload: bytes) -> bytes:
    # Simple TLV-like framing so multiple FUZZ_PARAM_STR() calls can slice meaningful parts
    # tag: 4 bytes ascii, len: 2 bytes big-endian, payload
    if len(tag) != 4:
        raise ValueError("tag must be 4 bytes")
    return tag + struct.pack(">H", len(payload)) + payload


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    parts: List[bytes] = []

    # Provide several 16-byte chunks for TraceId uses
    tid_kinds = ["all_zero", "all_ff", "low_nonzero", "high_nonzero", "alternating", "increasing", "random"]
    rng.shuffle(tid_kinds)
    for kind in tid_kinds[:5]:
        parts.append(_chunk(b"TID0", _mk_trace_id_pattern(kind, rng)))

    # Provide multiple 8-byte SpanIds
    sid_kinds = ["all_zero", "all_ff", "single_bit", "alternating", "random"]
    rng.shuffle(sid_kinds)
    for kind in sid_kinds:
        parts.append(_chunk(b"SID0", _mk_span_id_pattern(kind, rng)))

    # Several TraceOptions bytes
    for _ in range(4):
        parts.append(_chunk(b"TOPT", _mk_trace_options(rng)))

    # A few valid-looking names for absl::string_view in samplers and StartSpan
    for _ in range(6):
        parts.append(_chunk(b"NAME", _ascii_name(rng)))

    # Also include some arbitrary padding/random blobs for additional consumption
    for _ in range(3):
        blob_len = rng.randrange(4, 32)
        parts.append(_chunk(b"BLOB", _randbytes(rng, blob_len)))

    buf = b"".join(parts)

    # Ensure size limit
    if len(buf) > MAX_TOTAL:
        buf = buf[:MAX_TOTAL]

    return buf
